def c_acotado_otras_sin_coca(P, ctx, mod):
    cambios = {}
    aj = float(ctx.get("ajuste") or 1.0)
    if aj > 1.0:
        ctx["ajuste"] = 1.0
        cambios["ajuste"] = 1.0
    ctx["otrasPesoRf"] = 0.0
    cambios["otrasPesoRf"] = 0.0
    return P, ctx, cambios

def c_sin_autoajuste_sesgo50_dia7(P, ctx, mod):
    ctx["ajuste"] = 1.0
    ph = (mod.get("aciertos") or {}).get("por_horizonte") or {}
    pts = [(0, 0.0)]
    for h, v in ph.items():
        if (v.get("n") or 0) >= 30 and v.get("sesgo_m") is not None:
            pts.append((int(h), float(v["sesgo_m"])))
    pts.sort()
    if len(pts) < 3:
        return P, ctx, {"ajuste": 1.0}
    def s(t):
        for (h0, v0), (h1, v1) in zip(pts, pts[1:]):
            if t <= h1:
                return v0 + (v1 - v0) * (t - h0) / (h1 - h0)
        return pts[-1][1]
    c = mod.get("curva_mazar") or {"a": 3.6595, "b": 0.12497}
    cota_val = float(ctx.get("cota") or 2118.0)
    dvdz = c["a"] + c["b"] * max(0.0, cota_val - 2115.0)
    k = dvdz / 0.0864
    base = list(ctx.get("memoria") or [])
    corr = [0.0 if d < 7 else max(-80.0, min(80.0, -(s(d + 1) - s(d)) * k * 0.5)) for d in range(60)]
    n = max(len(base), len(corr))
    out = [round((base[i] if i < len(base) else 0.0) + (corr[i] if i < len(corr) else 0.0), 2) for i in range(n)]
    ctx["memoria"] = out
    return P, ctx, {"ajuste": 1.0, "memoria": out}

def c_paute_bruto_dia1(P, ctx, mod):
    bruta = mod.get("serieMazarBruta")
    actual = ctx.get("serieMazar")
    if not bruta or not actual or len(bruta) < 2 or len(actual) < 2:
        return None
    nueva = list(actual)
    nueva[1] = bruta[1]
    ctx["serieMazar"] = nueva
    return P, ctx, {"serieMazar": nueva}
